export async function alignSelection(mode: string) {
  const targets = [...multiSelection().nodes].map((id: string) => nodeById(id)).filter(Boolean);
  if (targets.length < 2) {
    toast('至少选中两个节点/器件才能对齐', 'info', 2400);
    return;
  }
  await pushUndoSnapshot();
  const xs = targets.map((node) => node!.position!.x);
  const ys = targets.map((node) => node!.position!.y);
  const minX = Math.min(...xs);
  const maxX = Math.max(...xs);
  const minY = Math.min(...ys);
  const maxY = Math.max(...ys);
  const positions = targets.map((node) => {
    let x = node!.position!.x;
    let y = node!.position!.y;
    if (mode === 'left') x = minX;
    else if (mode === 'right') x = maxX;
    else if (mode === 'centerX') x = (minX + maxX) / 2;
    else if (mode === 'top') y = minY;
    else if (mode === 'bottom') y = maxY;
    else if (mode === 'centerY') y = (minY + maxY) / 2;
    return { id: node!.id, position: { x: Math.round(x * 1000) / 1000, y: Math.round(y * 1000) / 1000 } };
  });
  try {
    await jsonRequest(ENDPOINTS.positions, 'POST', { positions });
    await refreshState(true);
    toast(`已对齐 ${targets.length} 个节点（${mode}）`, 'ok', 2200);
  } catch (error) {
    toast(`对齐失败：${(error as Error).message}`, 'error', 4000);
  }
}
export async function distributeSelection(axis: string) {
  const targets = [...multiSelection().nodes].map((id: string) => nodeById(id)).filter(Boolean);
  if (targets.length < 3) {
    toast('等距分布至少需要三个节点/器件', 'info', 2400);
    return;
  }
  await pushUndoSnapshot();
  const key = axis === 'y' ? 'y' : 'x';
  const sorted = [...targets].sort((a, b) => a!.position![key] - b!.position![key]);
  const first = sorted![0]!.position![key as 'x' | 'y'];
  const last = sorted![sorted.length - 1]!.position![key as 'x' | 'y'];
  const step = (last - first) / (sorted.length - 1);
  const positions = sorted.map((node, index: number) => {
    const value = index === 0 || index === sorted.length - 1
      ? node!.position![key]
      : first + step * index;
    const x = key === 'x' ? value : node!.position!.x;
    const y = key === 'y' ? value : node!.position!.y;
    return { id: node!.id, position: { x: Math.round(x * 1000) / 1000, y: Math.round(y * 1000) / 1000 } };
  });
  try {
    await jsonRequest(ENDPOINTS.positions, 'POST', { positions });
    await refreshState(true);
    toast(`已等距分布 ${targets.length} 个节点（${axis === 'y' ? '纵向' : '横向'}）`, 'ok', 2200);
  } catch (error) {
    toast(`分布失败：${(error as Error).message}`, 'error', 4000);
  }
}
export function selectWireNetwork(edge: EdgeItem) {
  // 从点击的导线出发遍历整个“导线连通网络”，否则分支后只会选中相邻导线，
  // 拖动时其余线段留在原地（设置拐点/连接点后尤其明显）。
  const adjacency = new Map<string, Array<{ edge: EdgeItem; other: string }>>();
  for (const item of state.scene?.edges || []) {
    if (item.kind !== 'wire') continue;
    if (!adjacency.has(item.source)) adjacency.set(item.source, []);
    if (!adjacency.has(item.target)) adjacency.set(item.target, []);
    adjacency.get(item.source)!.push({ edge: item, other: item.target });
    adjacency.get(item.target)!.push({ edge: item, other: item.source });
  }
  const endpoints = new Set<string>([edge.source, edge.target]);
  const selectedWires = new Map<string, EdgeItem>();
  if (edge.kind === 'wire') selectedWires.set(edge.id, edge);
  const queue = [edge.source, edge.target];
  while (queue.length) {
    const id = queue.shift()!;
    for (const link of adjacency.get(id) || []) {
      selectedWires.set(link.edge.id, link.edge);
      if (!endpoints.has(link.other)) {
        endpoints.add(link.other);
        queue.push(link.other);
      }
    }
  }
  state.multi.nodes = endpoints;
  state.multi.edges = new Set(selectedWires.keys());
  state.selection = { type: null, id: null };
  requestDraw();
  toast(`已选中 ${selectedWires.size} 条导线 / ${endpoints.size} 个端点`, 'info', 2200);
}
export async function addWireWaypoint(edge: EdgeItem) {
  const source = nodeById(edge.source);
  const target = nodeById(edge.target);
  if (!source || !target) return;
  const x = (source.position!.x + target.position!.x) / 2;
  const y = (source.position!.y + target.position!.y) / 2;
  const waypoints = [...(edge.waypoints || []), { x: Math.round(x * 100) / 100, y: Math.round(y * 100) / 100 }];
  try {
    await jsonRequest(ENDPOINTS.edge(edge.id), 'PATCH', {
      route: 'manual',
      waypoints,
    });
    await refreshState(true);
    state.selection = { type: 'edge', id: edge.id };
    renderInspector();
    requestDraw();
    toast(`已添加拐点（共 ${waypoints.length} 个）；可直接拖动拐点，画布会显示坐标`, 'ok', 2800);
  } catch (error) {
    toast(`添加拐点失败：${(error as Error).message}`, 'error', 4000);
  }
}
